import{_ as t,o as r,c as o,a2 as a}from"./chunks/framework.vLhlLNVn.js";const g=JSON.parse('{"title":"Wrong values and known bugs in older versions","description":"","frontmatter":{"order":2,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/en/04.fehlerbehebung/02.falsche-werte-und-bekannte-fehler.md"},"headers":[],"relativePath":"adapter/sourceanalytix/fehlerbehebung/falsche-werte-und-bekannte-fehler.md","filePath":"adapter/sourceanalytix/fehlerbehebung/falsche-werte-und-bekannte-fehler.md","lastUpdated":null}'),n={name:"adapter/sourceanalytix/fehlerbehebung/falsche-werte-und-bekannte-fehler.md"};function s(i,e,d,u,l,h){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="wrong-values-and-known-bugs-in-older-versions" tabindex="-1">Wrong values and known bugs in older versions <a class="header-anchor" href="#wrong-values-and-known-bugs-in-older-versions" aria-label="Permalink to &quot;Wrong values and known bugs in older versions&quot;">​</a></h1><p><a id="values-costs-far-too-high"></a></p><h2 id="values-or-costs-far-too-high-or-negative-–-is-the-unit-right" tabindex="-1">Values or costs far too high or negative – is the unit right? <a class="header-anchor" href="#values-or-costs-far-too-high-or-negative-–-is-the-unit-right" aria-label="Permalink to &quot;Values or costs far too high or negative – is the unit right?&quot;">​</a></h2><p><strong>In short:</strong> Usually a unit doesn&#39;t match. The source has a different unit selected than the device delivers, the price isn&#39;t given per unit of the price definition, or a start value was entered in the wrong unit. Check these places in the source detail, then correct the values.</p><h3 id="the-most-common-causes" tabindex="-1">The most common causes <a class="header-anchor" href="#the-most-common-causes" aria-label="Permalink to &quot;The most common causes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>What is wrong</th><th>What you see</th><th>Correct</th></tr></thead><tbody><tr><td>Source unit is <code>kWh</code>, but the device delivers <code>Wh</code></td><td>All values are 1,000 times too high</td><td>The unit the device delivers</td></tr><tr><td>Power and energy mixed up, for example <code>kW</code> instead of <code>kWh</code></td><td>A meter reading is summed up over time like a power value, and the values grow far too fast</td><td>Meter reading with an energy unit (<code>kWh</code>), power with <code>W</code> or <code>kW</code></td></tr><tr><td>&quot;Price per unit&quot; in cents instead of euros, for example <code>28.5</code> instead of <code>0.285</code></td><td>Costs 100 times too high</td><td>Price per unit of the price definition, so per kWh or per m³</td></tr><tr><td>Start value in <code>Wh</code>, but the price definition calculates in <code>kWh</code></td><td>Consumption strongly negative</td><td>Start value in the target unit</td></tr></tbody></table><p>The terms target unit, total and start value are explained under <a href="./../hintergrund/zaehler-reset#device-reset-detected-mean-reset">The terms</a>.</p><h3 id="how-to-check-it-from-v0-7-0" tabindex="-1">How to check it (from v0.7.0) <a class="header-anchor" href="#how-to-check-it-from-v0-7-0" aria-label="Permalink to &quot;How to check it (from v0.7.0)&quot;">​</a></h3><ol><li>Under &quot;Instances&quot;, open the settings of the SourceAnalytix instance and, on the &quot;Overview&quot; tab, your source.</li><li>Read &quot;Type&quot; at the top: it says, for example, &quot;Meter reading · kWh&quot; or &quot;Power · W → kWh&quot;. That is the measurement type and the target unit. Compare the &quot;Total&quot; with your meter.</li><li>Under &quot;Settings&quot;, check the &quot;Unit&quot; field. It must be the unit the device delivers. After the &quot;Price definition&quot;, its unit is shown in brackets.</li><li>On the &quot;Price definitions&quot; tab, check the &quot;Price per unit&quot; of the selected category.</li><li>Look at the &quot;Problems&quot; tab. A start value that doesn&#39;t fit appears there as &quot;Start value does not fit&quot;.</li></ol><p>From v0.7.0, SourceAnalytix checks start values as you enter them. If a start value only fits when divided by 1000, the field asks &quot;Looks like Wh – did you mean … ?&quot;. For more, see <a href="./../erste-schritte/erster-zaehler#start-values-unit">What do I enter for the start values (and in which unit)?</a>.</p><h3 id="repairing-values" tabindex="-1">Repairing values <a class="header-anchor" href="#repairing-values" aria-label="Permalink to &quot;Repairing values&quot;">​</a></h3><p>If you change the unit, SourceAnalytix doesn&#39;t correct values that are already written. Afterwards, bring the total in line with your meter using the &quot;Align meter reading&quot; action, and recalculate the costs with &quot;Recalculate costs from date&quot;. For how to repair consumption in running and completed periods, see <a href="./../anleitungen/zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Correcting wrong values</a>.</p><h3 id="no-folder-is-created-at-all-not-even-a-year-folder" tabindex="-1">No folder is created at all, not even a year folder <a class="header-anchor" href="#no-folder-is-created-at-all-not-even-a-year-folder" aria-label="Permalink to &quot;No folder is created at all, not even a year folder&quot;">​</a></h3><p>If SourceAnalytix doesn&#39;t recognise the unit at all, it doesn&#39;t start the source and creates no states, so no year folder either. This is described under <a href="./log-meldungen#error-unit-not-supported-no">Error &quot;unit not supported&quot; / &quot;No unit defined&quot;</a>.</p><p><strong>See also:</strong> <a href="./../anleitungen/quellen-und-einheiten#unit-datapoint-kwh-wh-m3">Which unit do I set on the datapoint (kWh instead of Wh, m³ instead of liters)?</a> · <a href="./../anleitungen/zaehlerstaende-korrigieren#values-negative-after-entering-start">Negative values after entering start values</a> · <a href="./../referenz/einstellungen#price-definition-structured-categories-base">How is a price definition structured (categories, basic fee, decimal mark)?</a></p><p><a id="after-update-restore-values-0"></a></p><h2 id="after-an-update-or-restore-values-are-0-or-sourceanalytix-is-missing" tabindex="-1">After an update or restore, values are 0 or SourceAnalytix is missing <a class="header-anchor" href="#after-an-update-or-restore-values-are-0-or-sourceanalytix-is-missing" aria-label="Permalink to &quot;After an update or restore, values are 0 or SourceAnalytix is missing&quot;">​</a></h2><p><strong>In short:</strong> After a restore, the adapter itself is often missing, because a backup saves settings and data, not the program code. In that case, reinstall SourceAnalytix from the &quot;latest&quot; repository. If values are 0 afterwards, or the total doesn&#39;t match your meter, align it from v0.7.0 with &quot;Align meter reading&quot;.</p><h3 id="sourceanalytix-is-missing-after-the-restore" tabindex="-1">SourceAnalytix is missing after the restore <a class="header-anchor" href="#sourceanalytix-is-missing-after-the-restore" aria-label="Permalink to &quot;SourceAnalytix is missing after the restore&quot;">​</a></h3><p>If the restore reports &quot;Unknown packetName&quot;, for example, or the instance doesn&#39;t start, the adapter isn&#39;t installed. SourceAnalytix is only available in the &quot;latest&quot; (beta) repository. Switch the repository and install SourceAnalytix as described under <a href="./../anleitungen/betrieb-und-wartung#update-sourceanalytix-downgrade">How do I update SourceAnalytix (and what is a downgrade)?</a>. The restored instance with its data then keeps running.</p><h3 id="values-0-or-errors-after-an-update-or-restore" tabindex="-1">Values 0 or errors after an update or restore <a class="header-anchor" href="#values-0-or-errors-after-an-update-or-restore" aria-label="Permalink to &quot;Values 0 or errors after an update or restore&quot;">​</a></h3><p>An update doesn&#39;t change your values. After a restore, however, the total in the <code>cumulativeReading</code> state and the offset in the datapoint&#39;s settings can come from different points in time. The total then no longer matches the meter.</p><p>How to check it (from v0.7.0):</p><ol><li>In the instance settings, open the source on the &quot;Overview&quot; tab and compare the &quot;Total&quot; with your meter. You&#39;ll find the offset under &quot;For experts&quot; as <code>valueAtDeviceReset</code>.</li><li>If the total is wrong, choose &quot;Align meter reading&quot; under &quot;Actions&quot; and enter the reading your meter shows.</li><li>Look at the &quot;Problems&quot; tab. You recover a &quot;Period rollover missed&quot; with &quot;Recover&quot;.</li></ol><p><strong>Up to v0.6.1</strong>, a source doesn&#39;t start if the offset is larger than the total. The log then shows &quot;Check settings for … Known valueAtDeviceReset …&quot;. From v0.6.2, it keeps running. For what to do then, see <a href="./log-meldungen#error-known-valueatdevicereset-known-cumulative">Error &quot;Known valueAtDeviceReset &gt; known cumulative value&quot;</a>.</p><p><strong>Up to v0.6.x:</strong> You can only see the offset in the datapoint&#39;s object under <code>common.custom.sourceanalytix.0</code> as <code>valueAtDeviceReset</code>. For how to set it and the total to matching values by hand, see <a href="./../anleitungen/zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Correcting wrong values</a>.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>If you move to a new system, take a full backup and don&#39;t restore it around midnight. That keeps the total and the settings together.</p></div><p><strong>See also:</strong> <a href="./../anleitungen/betrieb-und-wartung#data-back-up-move-new">Where is the data, how do I back it up and how do I move it?</a> · <a href="./../anleitungen/betrieb-und-wartung#iobroker-was-down-midnight-recover">ioBroker was off over midnight</a></p><p><a id="costs-stay-0-not-calculated"></a></p><h2 id="costs-stay-0-or-are-not-calculated" tabindex="-1">Costs stay 0 or are not calculated <a class="header-anchor" href="#costs-stay-0-or-are-not-calculated" aria-label="Permalink to &quot;Costs stay 0 or are not calculated&quot;">​</a></h2><p><strong>In short:</strong> Costs only appear if &quot;Costs&quot; is ticked for the source and the price definition has a valid &quot;Price per unit&quot;. Also check the &quot;Cost Type&quot; of the price definition: for &quot;Earnings&quot;, the values are under <code>earnings</code>, not under <code>costs</code>.</p><h3 id="checklist-from-v0-7-0" tabindex="-1">Checklist (from v0.7.0) <a class="header-anchor" href="#checklist-from-v0-7-0" aria-label="Permalink to &quot;Checklist (from v0.7.0)&quot;">​</a></h3><ol><li><strong>Is &quot;Costs&quot; ticked?</strong> Open the source and check the &quot;Costs&quot; box under &quot;Settings&quot;. Without it, SourceAnalytix doesn&#39;t create a <code>costs</code> or <code>earnings</code> folder. Change it, then click &quot;Apply&quot;.</li><li><strong>Is a price definition selected, and does it fit?</strong> If it&#39;s missing or its unit doesn&#39;t match, the source appears on the &quot;Problems&quot; tab (see <a href="./log-meldungen#error-no-cost-type-defined">Error &quot;No cost type defined&quot;</a>).</li><li><strong>Is the price valid?</strong> On the &quot;Price definitions&quot; tab, check the &quot;Price per unit&quot;. If it isn&#39;t a number, SourceAnalytix calculates with 0 and writes <code>Price definition &lt;name&gt; has no valid unit price &lt;value&gt;, using 0 to avoid invalid cost calculations</code> to the log.</li><li><strong>Is the price taken from a state?</strong> If the state doesn&#39;t deliver a valid price, SourceAnalytix uses the fallback price you entered: <code>Price source state &lt;state&gt; for &lt;name&gt; has no valid value or tariff, using configured fallback price &lt;price&gt;</code>. If that is empty, the costs are 0.</li><li><strong>Costs or earnings?</strong> With the &quot;Cost Type&quot; &quot;Earnings&quot; (feed-in), the values are under <code>sourceanalytix.0.&lt;device&gt;.currentYear.earnings</code> and the consumption under <code>currentYear.delivered</code>. In the source detail, the columns are called &quot;Delivery&quot; and &quot;Earnings&quot;.</li></ol><p>For costs, you don&#39;t need &quot;Store meter readings&quot;.</p><p>If you&#39;ve corrected the price or the tick, &quot;Recalculate costs from date&quot; on the source recalculates the costs from a date onward using the price history. The consumption stays the same.</p><p><strong>Up to v0.6.x:</strong> The box is called &quot;Calculate costs&quot; in the dialog at the datapoint. Since v0.5.0, missing or invalid prices no longer lead to invalid costs, but to 0 with a warning.</p><p><strong>See also:</strong> <a href="./../anleitungen/preise-und-kosten#assign-prices-create-custom-tariffs">Assigning prices and creating your own tariffs</a> · <a href="./../anleitungen/preise-und-kosten#costs-recalculated-change-price-change">Are calculated costs recalculated when I change the price, and how do I change it from a certain date?</a> · <a href="./../anleitungen/quellen-und-einheiten#track-pv-yield-feed-earnings">Recording PV yield and feed-in</a></p><p><a id="huge-consumption-after-power-outage"></a></p><h2 id="huge-consumption-on-power-sources-after-a-power-outage" tabindex="-1">Huge consumption on power sources after a power outage <a class="header-anchor" href="#huge-consumption-on-power-sources-after-a-power-outage" aria-label="Permalink to &quot;Huge consumption on power sources after a power outage&quot;">​</a></h2><p><strong>In short:</strong> With a power source, the last value applies until a new one arrives. If the device or the network goes down without reporting 0 first, SourceAnalytix extrapolates the last power over the whole gap. From v0.7.0, the &quot;Maximum gap between power values (minutes)&quot; setting prevents this.</p><h3 id="why-this-happens" tabindex="-1">Why this happens <a class="header-anchor" href="#why-this-happens" aria-label="Permalink to &quot;Why this happens&quot;">​</a></h3><p>SourceAnalytix multiplies each power value by the time until the next value. Up to v0.6.x, there is no upper limit for this. If no value arrived for three hours, three hours count at the last power. If SourceAnalytix itself was stopped, however, the first value after startup is just the new starting point, and the gap doesn&#39;t count at all.</p><h3 id="how-to-prevent-it-from-v0-7-0" tabindex="-1">How to prevent it (from v0.7.0) <a class="header-anchor" href="#how-to-prevent-it-from-v0-7-0" aria-label="Permalink to &quot;How to prevent it (from v0.7.0)&quot;">​</a></h3><ol><li>In the SourceAnalytix instance settings, open the power source on the &quot;Overview&quot; tab.</li><li>In the &quot;Settings&quot; section, enter a value for &quot;Maximum gap between power values (minutes)&quot; that is clearly larger than the longest normal interval between two values from your device.</li><li>Click &quot;⚡ Apply&quot;. A longer stretch without a value then counts as 0. The log shows <code>No new power value from &lt;datapoint&gt; for &lt;n&gt; min, longer than the maximum gap of &lt;m&gt; min; this interval is not counted</code>.</li></ol><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Leave the setting empty or at 0 if your device only sends when something changes. Otherwise, the consumption of long stretches at constant power is missing, for example a heater that runs for hours at the same power.</p></div><p>If a power source doesn&#39;t deliver a value for three hours, then from v0.7.0 it appears on the &quot;Problems&quot; tab with &quot;Power source has not reported for a long time&quot;.</p><p><strong>Up to v0.6.x:</strong> Make sure the device reports 0 when it&#39;s switched off, or use a meter reading (kWh) instead of the power if the device has one (see <a href="./../erste-schritte/erster-zaehler#datapoint-enable-meter-kwh-power">Which datapoint do I activate: meter (kWh) or power (W)?</a>).</p><p>You repair values that are already booked as described under <a href="./../anleitungen/zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Correcting wrong values</a>.</p><p><strong>See also:</strong> <a href="./../hintergrund/berechnung#sourceanalytix-convert-watts-kwh">How does SourceAnalytix convert watts to kWh?</a></p><p><a id="so-many-decimals"></a></p><h2 id="why-so-many-decimal-places" tabindex="-1">Why so many decimal places? <a class="header-anchor" href="#why-so-many-decimal-places" aria-label="Permalink to &quot;Why so many decimal places?&quot;">​</a></h2><p><strong>In short:</strong> By default, SourceAnalytix rounds consumption to 3 and costs to 2 decimal places. Each source has its own setting. From v0.7.0, you change it in the source detail under &quot;For experts&quot;. With <code>-1</code>, SourceAnalytix stores the value without rounding, which gives many decimal places.</p><h3 id="where-to-set-the-rounding" tabindex="-1">Where to set the rounding <a class="header-anchor" href="#where-to-set-the-rounding" aria-label="Permalink to &quot;Where to set the rounding&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Where</th><th>Fields</th><th>Applies to</th></tr></thead><tbody><tr><td>Instance settings, &quot;Main settings&quot;, &quot;Rounding&quot; section</td><td>&quot;Decimals for consumption values&quot; (default 3), &quot;Decimals for cost values&quot; (default 2)</td><td>only sources that are newly set up</td></tr><tr><td>Source detail, &quot;Settings&quot;, &quot;For experts&quot; (from v0.7.0)</td><td>&quot;Decimals for consumption&quot;, &quot;Decimals for costs&quot;</td><td>this source, after &quot;Apply&quot;</td></tr></tbody></table><p>Existing sources keep their rounding, even if you change the instance default. Since v0.6.0, each source stores its own value.</p><h3 id="why-does-it-show-402-400" tabindex="-1">Why does it show 402.400? <a class="header-anchor" href="#why-does-it-show-402-400" aria-label="Permalink to &quot;Why does it show 402.400?&quot;">​</a></h3><p>SourceAnalytix writes a number, for example <code>402.4</code>. How many digits, zeros or thousands separators you see is determined by the display, so VIS, Admin or your visualisation.</p><p><strong>Up to v0.5.4:</strong> The number of decimal places can&#39;t be set. From v0.5.5, you can set it for the instance and per source (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/934" target="_blank" rel="noreferrer">#934</a>).</p><p><strong>See also:</strong> <a href="./../referenz/einstellungen#instance-settings-exist-periods-decimals">Which instance settings are there (periods, decimals)?</a></p><p><a id="known-bugs-older-versions-please"></a></p><h2 id="known-bugs-in-older-versions-–-please-update" tabindex="-1">Known bugs in older versions – please update <a class="header-anchor" href="#known-bugs-in-older-versions-–-please-update" aria-label="Permalink to &quot;Known bugs in older versions – please update&quot;">​</a></h2><p><strong>In short:</strong> Many bugs from the forum and issues are fixed in newer versions. Check the table to see from which version your bug is fixed, and update SourceAnalytix. Up to v0.6.1, there are a number of known bugs that are fixed from v0.6.2.</p><p>For how to update, see <a href="./../anleitungen/betrieb-und-wartung#update-sourceanalytix-downgrade">How do I update SourceAnalytix (and what is a downgrade)?</a>. SourceAnalytix is currently only available in the &quot;latest&quot; (beta) repository.</p><h3 id="up-to-v0-6-1-fixed-from-v0-6-2" tabindex="-1">Up to v0.6.1, fixed from v0.6.2 <a class="header-anchor" href="#up-to-v0-6-1-fixed-from-v0-6-2" aria-label="Permalink to &quot;Up to v0.6.1, fixed from v0.6.2&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Bug up to v0.6.1</th><th>Fixed from v0.6.2</th><th>More</th></tr></thead><tbody><tr><td>A meter reading of exactly 0 is not written to the meter readings (<code>meterReadings</code>).</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1253" target="_blank" rel="noreferrer">#1253</a></td><td><a href="./../referenz/states-und-meldungen#meter-readings-cumulative">Meter readings</a></td></tr><tr><td>Power sources (W) lose the energy between the last value and midnight at every period rollover.</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1254" target="_blank" rel="noreferrer">#1254</a></td><td><a href="./../erste-schritte/erster-zaehler#datapoint-enable-meter-kwh-power">Which datapoint do I activate: meter (kWh) or power (W)?</a></td></tr><tr><td>Meter readings delivered as text, for example <code>&quot;12,5&quot;</code>, are not calculated.</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1255" target="_blank" rel="noreferrer">#1255</a></td><td><a href="./log-meldungen#source-delivers-text-instead-number">Source delivers text</a></td></tr><tr><td>In the year archive, 29 to 31 December overwrite week 01 of January.</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1256" target="_blank" rel="noreferrer">#1256</a></td><td><a href="./../hintergrund/perioden-und-zeit#week-52-53-have-values">Weeks 52 and 53</a></td></tr><tr><td>&quot;Known valueAtDeviceReset &gt; known cumulative value&quot;: the source doesn&#39;t start.</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1257" target="_blank" rel="noreferrer">#1257</a></td><td><a href="./log-meldungen#error-known-valueatdevicereset-known-cumulative">Error &quot;Known valueAtDeviceReset&quot;</a></td></tr><tr><td>If a device reports 0 twice and then goes back to the old value, the total doubles.</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1258" target="_blank" rel="noreferrer">#1258</a></td><td><a href="./../hintergrund/zaehler-reset#device-reset-detected-mean-reset">Reset detection</a></td></tr><tr><td><code>currentPrice</code> only changes after a restart when a &quot;Valid from&quot; lies in the future. The costs are still correct.</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1259" target="_blank" rel="noreferrer">#1259</a></td><td><a href="./../referenz/states-und-meldungen#prices-read-written-as-states">Prices as states</a></td></tr><tr><td>If ioBroker was off over midnight, all the consumption of the gap lands on the new day.</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1260" target="_blank" rel="noreferrer">#1260</a></td><td><a href="./log-meldungen#midnight-crash-rollover-wrong-time">Midnight</a></td></tr><tr><td>Runtime errors don&#39;t appear in the log without Sentry.</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1261" target="_blank" rel="noreferrer">#1261</a></td><td>–</td></tr><tr><td>&quot;Cumulative reading … decreased while reset detection is disabled&quot; fills the log.</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1262" target="_blank" rel="noreferrer">#1262</a></td><td><a href="./log-meldungen#high-cpu-memory-use-too">Too much log output</a></td></tr><tr><td>Units such as <code>m3</code> or <code>kwh</code> on the datapoint are not recognised.</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1264" target="_blank" rel="noreferrer">#1264</a></td><td><a href="./log-meldungen#error-unit-not-supported-no">Error &quot;No unit defined&quot;</a></td></tr><tr><td><code>km³</code>, <code>dm³</code>, <code>cm³</code>, <code>mm³</code>, <code>µm</code> and <code>nm</code> are converted incorrectly. Mismatched units only show up during calculation.</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1278" target="_blank" rel="noreferrer">#1278</a></td><td><a href="./../referenz/einstellungen#units-supported-energy-volume-weight">Units</a></td></tr><tr><td>Permanently high CPU load, because sources are rebuilt on every object change.</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1233" target="_blank" rel="noreferrer">#1233</a></td><td><a href="./log-meldungen#high-cpu-memory-use-too">High CPU load</a></td></tr></tbody></table><h3 id="older-bugs" tabindex="-1">Older bugs <a class="header-anchor" href="#older-bugs" aria-label="Permalink to &quot;Older bugs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>What you see</th><th>Fixed in</th><th>Source</th></tr></thead><tbody><tr><td>&quot;Cannot load jsonConfig of sourceanalytix: Not exists&quot;</td><td>v0.4.9</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/453" target="_blank" rel="noreferrer">#453</a></td></tr><tr><td>Values are reset to 0 at night or double (source datapoint with default value 0)</td><td>v0.4.8</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/210" target="_blank" rel="noreferrer">#210</a></td></tr><tr><td>Daily values are not reset to 0 at midnight when the source value doesn&#39;t change</td><td>v0.5.0</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/478" target="_blank" rel="noreferrer">#478</a></td></tr><tr><td>The folder for the new year is not created</td><td>v0.5.0</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/481" target="_blank" rel="noreferrer">#481</a></td></tr><tr><td>Reset detection doesn&#39;t work, or reports resets although it is switched off</td><td>v0.5.0</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/686" target="_blank" rel="noreferrer">#686</a>, <a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/794" target="_blank" rel="noreferrer">#794</a></td></tr><tr><td>The basic fee is counted twice after a restart</td><td>v0.5.4</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1188" target="_blank" rel="noreferrer">#1188</a></td></tr><tr><td>A missed period rollover is only recovered with a restart</td><td>v0.5.5</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/905" target="_blank" rel="noreferrer">#905</a></td></tr><tr><td>Previous periods appear one day late in Flot, History or Grafana</td><td>v0.5.5</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/497" target="_blank" rel="noreferrer">#497</a></td></tr><tr><td>A brief drop to 0 or to a lower value is immediately treated as a reset, and consumption doubles</td><td>v0.6.0</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1199" target="_blank" rel="noreferrer">#1199</a></td></tr><tr><td>Price definition and unit stay empty in Admin 8</td><td>v0.6.0</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1202" target="_blank" rel="noreferrer">#1202</a></td></tr><tr><td>A brief downward outlier that returns to the old value is confirmed as a reset</td><td>v0.6.1</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1227" target="_blank" rel="noreferrer">#1227</a></td></tr></tbody></table><p>The many old messages about day, week and month rollovers from versions 0.2 to 0.4 were resolved by the rebuild in v0.5.0. If you&#39;re still using one of those versions, update to at least v0.5.0, or better still to the current version.</p><p><strong>From v0.7.0:</strong> The instance settings get the &quot;Overview&quot; and &quot;Problems&quot; tabs. The &quot;Problems&quot; tab shows many of this page&#39;s errors directly, with a button to fix them. For this, SourceAnalytix needs Admin 8.0.0 or newer (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1269" target="_blank" rel="noreferrer">#1269</a>).</p><p><strong>See also:</strong> <a href="./../anleitungen/betrieb-und-wartung#update-sourceanalytix-downgrade">How do I update SourceAnalytix (and what is a downgrade)?</a> · <a href="./log-meldungen#error-unit-not-supported-no">Log messages and errors during setup</a></p>',70)])])}const p=t(n,[["render",s]]);export{g as __pageData,p as default};
